<?php
try{$effective=chr_assignment($pdo,$id,date('Y-m-d'));}catch(InvalidArgumentException $e){$effective=null;echo '<div class="alert error">'.h($e->getMessage()).'</div>';}
?><section class="card"><h2>Attendance & Shift</h2><p>Current effective shift: <strong><?=h($effective['title']??'Unassigned')?></strong> · Source: <?=h($effective['assignment_source']??'None')?></p><?php if(can($pdo,$user,'shifts.manage')):?><form method="post" class="form-grid core-form"><?php ftoken();?><input type="hidden" name="action" value="core_config"><input type="hidden" name="module" value="roster"><input type="hidden" name="employee_id" value="<?=$id?>"><input type="hidden" name="title" value="Employee shift override"><input type="hidden" name="active" value="1"><label>Assign different shift<select name="shift_id" required><option value="">Select shift</option><?php foreach(chr_rows($pdo,'shifts') as $s)if($s['status']==='Active'):?><option value="<?=(int)$s['id']?>"><?=h($s['title'])?></option><?php endif;?></select></label><?php field('from','Effective from',['from'=>date('Y-m-d')],'date',true);field('to','Effective to (optional)',[],'date');field('notes','Reason',[],'text',true,2000);?><div class="full"><button class="button primary">Assign individual override</button> <a class="button" href="?page=roster">Manage assignment end dates</a></div></form><?php endif;?><?php $history=[];$ctx=att_resolution_context($pdo);$profileEmployee=chr_employee($pdo,$id);$departments=[(int)($profileEmployee['department_id']??0)];foreach($ctx['department_history'][$id]??[] as $change){$departments[]=(int)$change['values']['before'];$departments[]=(int)$change['values']['after'];}foreach(chr_rows($pdo,'roster') as $r)if((int)$r['employee_id']===$id){$r['assignment_type']='Employee';$history[]=$r;}foreach($ctx['defaults'] as $r)if(($r['values']['scope']??'')==='Company'||in_array((int)($r['values']['department_id']??0),$departments,true)){$r['assignment_type']=$r['values']['scope'];$history[]=$r;}usort($history,fn($a,$b)=>strcmp($b['values']['from'],$a['values']['from']));?><h3>Assignment history</h3><p>Company and department defaults apply only when no higher-priority assignment covers the date.</p><div class="table-scroll"><table class="directory"><thead><tr><th>Shift</th><th>Type</th><th>From</th><th>To</th><th>Assigned by</th><th>Reason</th><th>Status</th></tr></thead><tbody><?php foreach($history as $r):$d=$r['values'];$s=chr_record($pdo,'shifts',(int)$d['shift_id']);$q=$pdo->prepare('SELECT name FROM users WHERE id=?');$q->execute([$r['created_by']]);?><tr><td><?=h($s['title']??'Unavailable')?></td><td><?=h($r['assignment_type'])?></td><td><?=h($d['from'])?></td><td><?=h($d['to']??'Ongoing')?></td><td><?=h($q->fetchColumn())?><small><?=h($r['created_at'])?></small></td><td><?=h($d['reason']??$d['notes']??'')?></td><td><?=h($r['status'])?></td></tr><?php endforeach;?></tbody></table></div></section>
